134			t.Fatalf("audit: %v %v", recs, err)
135		}
136		if recs[0].Revision != 1 || recs[1].Revision != 2 {
137			t.Fatalf("audit order: %d %d", recs[0].Revision, recs[1].Revision)
138		}
139		if recs[0].Operator != "alice" || !recs[0].Time.Equal(base) {
140			t.Fatalf("audit meta: %+v", recs[0])
141		}
142		if string(recs[0].Before) != "{}" || string(recs[0].After) != `{"a":1}` {
143			t.Fatalf("audit configs: %s -> %s", recs[0].Before, recs[0].After)
144		}
