169		if err := s.Report("dev-1", 1, base, "1.1", json.RawMessage(`{"cpu":80}`)); err != nil {
170			t.Fatal(err)
171		}
172		v, _ := s.Get("dev-1")
173		if !v.Online || v.Version != "1.1" || v.LastSeq != 1 || string(v.Reported) != `{"cpu":80}` {
174			t.Fatalf("after report: %+v", v)
175		}
