97							ErrCorruptStorage, id, dd.DeviceID)
98					}
99				}
100				if matches != 1 {
101					return fmt.Errorf("%w: batch request %s device %s audit missing",
102						ErrCorruptStorage, id, dd.DeviceID)
103				}
104				devRevs[dd.DeviceID] = dd.NewRevision
105				rec.Devices = append(rec.Devices, batchDeviceState{
106					DeviceID:    dd.DeviceID,
107					Revision:    dd.Revision,
108					NewRevision: dd.NewRevision,
109					Config:      cloneRaw(dd.Config),
110				})
111			}
112			expected[id] = devRevs
113			out[id] = rec
114		}
115		// 反向核对：审计中的非空请求标识必须对应一条实际包含该设备、且新修订号
116		// 一致的批量记录（单设备修改的审计标识为空，无需补填）。
117		for devID, dev := range s.devices {
118			for _, a := range dev.Audit {
119				if a.RequestID == "" {
120					continue
121				}
122				devs, ok := expected[a.RequestID]
123				if !ok {
