		`"version":"1.0","online":false,"revision":2,` +
		`"desired":{ "a": 1.0 },"reported":{},"lastSeq":0,` +
		`"audit":[` +
		// 时间晚于第二条；after 用 1 与期望中的 1.0 按数值比较
		`{"operator":"alice","time":"2026-10-02T12:05:00Z","revision":1,"before":{ },"after":{"a":1}},` +
		// before 字段顺序、空白不同，语义仍等于上一条 after
		`{"operator":"bob","time":"2026-10-02T12:00:00Z","revision":2,"before":{ "a" : 1 },"after":{"a":1.0}]}}}`
	dir := writeStore(t, body)
