// 任一设备历史缺失、断开或与当前期望不符都拒绝打开整个存储，
// 且原文件内容保持不变。
func TestRestoreAuditChainCorruptRefused(t *testing.T) {
	cases := map[string]string{
		// 删掉修订号 1 的审计，只留修订号 2 与当前影子
		"first audit missing": `{"format":1,"devices":{"dev-1":{` +
			`"version":"1.0","online":false,"revision":2,"desired":{"a":2},"reported":{},` +
			`"audit":[{"operator":"bob","time":"2026-10-02T12:01:00Z","revision":2,"before":{"a":1},"after":{"a":2}}]}}}`,
		// 修订号断开：1 之后直接是 3
		"revision gap": `{"format":1,"devices":{"dev-1":{` +
			`"version":"1.0","online":false,"revision":2,"desired":{"a":2},"reported":{},` +
			`"audit":[` +
			`{"operator":"alice","time":"2026-10-02T12:00:00Z","revision":1,"before":{},"after":{"a":1}},` +
			`{"operator":"bob","time":"2026-10-02T12:01:00Z","revision":3,"before":{"a":1},"after":{"a":2}}]}}}`,
		// 审计从修订号 2 开始
		"audit not from one": `{"format":1,"devices":{"dev-1":{` +
			`"version":"1.0","online":false,"revision":2,"desired":{"a":1},"reported":{},` +
			`"audit":[{"operator":"bob","time":"2026-10-02T12:01:00Z","revision":2,"before":{"a":1},"after":{"a":1}}]}}}`,
		// 首条修改前不是登记时的空对象
		"first before not empty": `{"format":1,"devices":{"dev-1":{` +
			`"version":"1.0","online":false,"revision":1,"desired":{"a":1},"reported":{},` +
			`"audit":[{"operator":"op","time":"2026-10-02T12:00:00Z","revision":1,"before":{"x":1},"after":{"a":1}}]}}}`,
		// 相邻记录断开：第二条修改前不等于第一条修改后
		"chain broken": `{"format":1,"devices":{"dev-1":{` +
			`"version":"1.0","online":false,"revision":2,"desired":{"a":2},"reported":{},` +
			`"audit":[` +
			`{"operator":"alice","time":"2026-10-02T12:00:00Z","revision":1,"before":{},"after":{"a":1}},` +
			`{"operator":"bob","time":"2026-10-02T12:01:00Z","revision":2,"before":{"a":9},"after":{"a":2}}]}}}`,
		// 末条修改后与当前期望配置不同
		"last after mismatches desired": `{"format":1,"devices":{"dev-1":{` +
			`"version":"1.0","online":false,"revision":2,"desired":{"a":3},"reported":{},` +
			`"audit":[` +
			`{"operator":"alice","time":"2026-10-02T12:00:00Z","revision":1,"before":{},"after":{"a":1}},` +
			`{"operator":"bob","time":"2026-10-02T12:01:00Z","revision":2,"before":{"a":1},"after":{"a":2}}]}}}`,
		// 当前修订号大于审计条数：历史解释不了现状
		"revision beyond audit": `{"format":1,"devices":{"dev-1":{` +
			`"version":"1.0","online":false,"revision":3,"desired":{"a":2},"reported":{},` +
			`"audit":[` +
			`{"operator":"alice","time":"2026-10-02T12:00:00Z","revision":1,"before":{},"after":{"a":1}},` +
			`{"operator":"bob","time":"2026-10-02T12:01:00Z","revision":2,"before":{"a":1},"after":{"a":2}}]}}}`,
		// 有审计却声称修订号 0
		"audit with revision zero": `{"format":1,"devices":{"dev-1":{` +
			`"version":"1.0","online":false,"revision":0,"desired":{},"reported":{},` +
			`"audit":[{"operator":"op","time":"2026-10-02T12:00:00Z","revision":1,"before":{},"after":{}}]}}}`,
		// 修订号 0、无审计，但期望配置不是空对象
		"desired not empty at revision zero": `{"format":1,"devices":{"dev-1":{` +
			`"version":"1.0","online":false,"revision":0,"desired":{"a":1},"reported":{}}}}`,
	}
	for name, body := range cases {
		t.Run(name, func(t *testing.T) {
			dir := writeStore(t, body)
			s, err := Open(dir)
			if err == nil {
				s.Close()
				t.Fatalf("expected ErrCorruptStorage")
			}
			if !errors.Is(err, ErrCorruptStorage) {
				t.Fatalf("error must wrap ErrCorruptStorage: %v", err)
			}
			// 原文件内容保持不变
			data, rerr := os.ReadFile(filepath.Join(dir, storeFileName))
			if rerr != nil {
				t.Fatal(rerr)
			}
			if string(data) != body {
				t.Fatalf("corrupt file modified on rejected open")
			}
		})
	}
}

// 一台设备损坏即拒绝打开整个存储，其他正常设备也不可用。
func TestRestoreOneDeviceCorruptRejectsAll(t *testing.T) {
	body := `{"format":1,"devices":{` +
		`"good":{"version":"1.0","online":false,"revision":0,"desired":{},"reported":{}},` +
		`"bad":{"version":"1.0","online":false,"revision":1,"desired":{"a":1},"reported":{},` +
		`"audit":[{"operator":"op","time":"2026-10-02T12:00:00Z","revision":1,"before":{},"after":{"a":2}}]}}}`
	dir := writeStore(t, body)
	if _, err := Open(dir); !errors.Is(err, ErrCorruptStorage) {
		t.Fatalf("whole store must be refused when one device history mismatches: %v", err)
	}
}

